/**
 * Story 42.8 (AC 42.8.1, AC 42.8.3; AD-28, AD-2, Rule #45) - the Claude Code plugin the skills-pack directory carries, checked across packages.
 *
 * The plugin root is `packages/client-config/skills-pack/` (generated by `gen:pack` from `skills-pack-src/plugin/`); `@iris-mcp/all` is the only
 * package that can see all five servers, so the cross-package claims live here:
 *  - `.mcp.json` launches exactly the five servers of client-config's `PKG_BY_SERVER`, pinned with its `pinnedSpec`, under the short keys
 *    `dev`, `admin`, `data`, `interop` and `ops`;
 *  - every `${user_config.<key>}` that a server reads names an option that is `required` or has a `default` (an unset option with no default
 *    substitutes the empty string, which `loadConfig` reads as a broken host or port; Claude Code 2.1.330 probe of 2026-11-21);
 *  - the six `userConfig` options map onto the six connection variables, the same ones the registry listings declare, client-config's
 *    `CONNECTION_VARS` plus the password, and the defaults of `loadConfig`;
 *  - the install key `iris-mcp@iris-mcp` the installer detects is the plugin's name at the marketplace's name;
 *  - the longest `mcp__plugin_iris-mcp_<key>__<tool>` over every built server's tools is at most 64 characters (the limit of common clients);
 *  - the plugin carries no hook, no rule and no `CLAUDE.md` (AC 42.8.3: the compile-on-save hook is a candidate, not shipped).
 * The tests read the generated files, so they fail when a source changes without `pnpm gen:pack`.
 */

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import { CONNECTION_VARIABLES } from "../../../../scripts/lib/listings.mjs";
import { loadAllTools } from "../../../../scripts/lib/tool-catalog.mjs";
import { MARKETPLACE_NAME, PACK_DIR, PLUGIN_NAME, PLUGIN_SERVER_KEYS } from "../../../../scripts/lib/skills-pack.mjs";
import { REPO_ROOT } from "./pack-fixture";
import { staleDistReason } from "./process-gate-helpers.js";

type ClientConfigDist = {
  PKG_BY_SERVER: Record<string, string>;
  pinnedSpec: (pkg: string) => string;
  CLAUDE_CODE_PLUGIN_ID: string;
};

interface UserConfigOption {
  type: string;
  title: string;
  description: string;
  default?: string | number | boolean;
  required?: boolean;
  sensitive?: boolean;
}

const read = (relative: string): any => JSON.parse(readFileSync(join(REPO_ROOT, relative), "utf8"));
const PLUGIN = (): { name: string; version: string; userConfig: Record<string, UserConfigOption>; [key: string]: unknown } => read(`${PACK_DIR}/.claude-plugin/plugin.json`);
const SERVERS = (): Record<string, { command: string; args: string[]; env: Record<string, string> }> => read(`${PACK_DIR}/.mcp.json`).mcpServers;

/** The short key of each server package's directory: `iris-dev-mcp` is `dev`. */
const keyOfPackage = (pkg: string): string => pkg.replace(/^iris-/, "").replace(/-mcp$/, "");

/** The connection variable each option sets, by option key. */
const OPTION_TO_VARIABLE: Record<string, string> = {
  iris_host: "IRIS_HOST",
  iris_port: "IRIS_PORT",
  iris_namespace: "IRIS_NAMESPACE",
  iris_https: "IRIS_HTTPS",
  iris_username: "IRIS_USERNAME",
  iris_password: "IRIS_PASSWORD",
};

let dist: ClientConfigDist;

beforeAll(async () => {
  const stale = staleDistReason(REPO_ROOT, "client-config");
  if (stale !== undefined) throw new Error(`Build client-config first (pnpm --filter @iris-mcp/client-config build): ${stale}`);
  dist = (await import(pathToFileURL(join(REPO_ROOT, "packages/client-config/dist/index.js")).href)) as ClientConfigDist;
}, 60_000);

describe(".mcp.json: the five servers, pinned, under short keys (decisions #101 and #105)", () => {
  it("the keys are dev, admin, data, interop and ops", () => {
    expect(Object.keys(SERVERS()).sort()).toEqual(["admin", "data", "dev", "interop", "ops"]);
    expect([...PLUGIN_SERVER_KEYS].sort()).toEqual(Object.keys(SERVERS()).sort());
  });

  it("each server runs `npx -y <pinnedSpec(package)>`, the package of PKG_BY_SERVER, and nothing else launches", () => {
    const expected = Object.fromEntries(Object.entries(dist.PKG_BY_SERVER).map(([server, pkg]) => [keyOfPackage(server), ["-y", dist.pinnedSpec(pkg)]]));
    const actual = Object.fromEntries(Object.entries(SERVERS()).map(([key, server]) => [key, server.args]));
    expect(actual).toEqual(expected);
    for (const server of Object.values(SERVERS())) expect(server.command).toBe("npx");
    expect(Object.values(actual).map((args) => args[1])).toEqual(expect.arrayContaining(["@iris-mcp/dev@1", "@iris-mcp/interop@1"]));
  });

  it("no server lists an environment variable other than the six connection variables", () => {
    for (const [key, server] of Object.entries(SERVERS())) {
      expect(Object.keys(server.env).sort(), key).toEqual(Object.values(OPTION_TO_VARIABLE).sort());
    }
  });
});

describe("userConfig: the six connection options (decision #104)", () => {
  it("are exactly host, port, namespace, https, username and password", () => {
    expect(Object.keys(PLUGIN().userConfig).sort()).toEqual(Object.keys(OPTION_TO_VARIABLE).sort());
  });

  it("every ${user_config.X} a server reads names an option that is required or has a default, so it never substitutes the empty string", () => {
    const options = PLUGIN().userConfig;
    const referenced = new Set<string>();
    for (const server of Object.values(SERVERS())) {
      for (const value of Object.values(server.env)) {
        for (const match of value.matchAll(/\$\{user_config\.([A-Za-z0-9_]+)\}/g)) referenced.add(match[1] as string);
      }
    }
    expect([...referenced].sort()).toEqual(Object.keys(OPTION_TO_VARIABLE).sort());
    for (const key of referenced) {
      const option = options[key];
      expect(option, `${key} is declared`).toBeDefined();
      expect(option?.required === true || option?.default !== undefined, `${key} is required or has a default`).toBe(true);
    }
  });

  it("each option maps to its IRIS_* variable in every server's env, as ${user_config.<key>}", () => {
    for (const [serverKey, server] of Object.entries(SERVERS())) {
      for (const [option, variable] of Object.entries(OPTION_TO_VARIABLE)) {
        expect(server.env[variable], `${serverKey} ${variable}`).toBe(`\${user_config.${option}}`);
      }
    }
  });

  it("the defaults are loadConfig's own (localhost, 52773, USER, false), the username and password are required, and only the password is sensitive", async () => {
    const { loadConfig } = (await import(pathToFileURL(join(REPO_ROOT, "packages/shared/dist/config.js")).href)) as { loadConfig: (env: Record<string, string>) => Record<string, any> };
    const defaults = loadConfig({ IRIS_USERNAME: "u", IRIS_PASSWORD: "p" });
    const options = PLUGIN().userConfig;
    expect(options["iris_host"]?.default).toBe(defaults["host"]);
    expect(options["iris_port"]?.default).toBe(defaults["port"]);
    expect(options["iris_namespace"]?.default).toBe(defaults["namespace"]);
    expect(options["iris_https"]?.default).toBe(defaults["https"]);
    expect(options["iris_port"]?.type).toBe("number");
    expect(options["iris_https"]?.type).toBe("boolean");
    expect(options["iris_username"]?.required).toBe(true);
    expect(options["iris_password"]?.required).toBe(true);
    expect(Object.entries(options).filter(([, option]) => option.sensitive === true).map(([key]) => key)).toEqual(["iris_password"]);
    expect(options["iris_username"]?.default, "a required option has no default").toBeUndefined();
  });

  it("the plugin's options, the registry listings' variables and client-config's CONNECTION_VARS are the same six variables, with the same defaults", () => {
    const registry = Object.fromEntries((CONNECTION_VARIABLES as Array<{ name: string; default?: string; required?: boolean; secret?: boolean }>).map((entry) => [entry.name, entry]));
    expect(Object.keys(registry).sort()).toEqual(Object.values(OPTION_TO_VARIABLE).sort());
    // client-config's connection variables (synthesize.ts), read from source because the constant is not exported: the registry's six less the password.
    const synthesize = readFileSync(join(REPO_ROOT, "packages/client-config/src/synthesize.ts"), "utf8");
    const declared = /const CONNECTION_VARS = \[([^\]]+)\] as const;/.exec(synthesize)?.[1]?.match(/"(IRIS_[A-Z]+)"/g)?.map((text) => text.replaceAll('"', ""));
    expect([...(declared ?? []), "IRIS_PASSWORD"].sort()).toEqual(Object.keys(registry).sort());
    for (const [option, variable] of Object.entries(OPTION_TO_VARIABLE)) {
      const entry = registry[variable];
      const planned = PLUGIN().userConfig[option];
      expect(String(planned?.default ?? ""), `${variable}'s default`).toBe(String(entry?.default ?? ""));
      expect(planned?.required === true, `${variable} is required`).toBe(entry?.required === true);
      expect(planned?.sensitive === true, `${variable} is secret`).toBe(entry?.secret === true);
    }
  });
});

describe("names", () => {
  it("the installer's plugin id is <plugin name>@<marketplace name>, from the generated plugin.json and the marketplace", () => {
    const marketplace = read(".claude-plugin/marketplace.json");
    expect(PLUGIN().name).toBe(PLUGIN_NAME);
    expect(marketplace.name).toBe(MARKETPLACE_NAME);
    expect(marketplace.plugins.map((entry: { name: string }) => entry.name)).toEqual([PLUGIN().name]);
    expect(dist.CLAUDE_CODE_PLUGIN_ID).toBe(`${PLUGIN().name}@${marketplace.name}`);
    expect(dist.CLAUDE_CODE_PLUGIN_ID).toBe("iris-mcp@iris-mcp");
  });

  it("the plugin's version is the shared version, and the marketplace pins the release tag with git-subdir at the plugin root (no relative path)", () => {
    const shared = read("packages/client-config/package.json").version as string;
    expect(PLUGIN().version).toBe(shared);
    const source = read(".claude-plugin/marketplace.json").plugins[0].source;
    expect(source).toEqual({ source: "git-subdir", url: "https://github.com/jbrandtmse/iris-execute-mcp-v2.git", path: PACK_DIR, ref: `v${shared}` });
  });

  it("the longest mcp__plugin_iris-mcp_<key>__<tool> over every built server's tools, and the framework's own tool, is at most 64 characters", async () => {
    const tools = (await loadAllTools(REPO_ROOT)) as Array<{ pkg: string; tool: { name: string } }>;
    expect(tools.length).toBeGreaterThan(100);
    // The key each package really has in .mcp.json: the one whose launch spec is that package's.
    const keyOf = (pkg: string): string => {
      const spec = dist.pinnedSpec(dist.PKG_BY_SERVER[pkg] as string);
      const found = Object.entries(SERVERS()).find(([, server]) => server.args[1] === spec);
      expect(found, `no .mcp.json server launches ${spec}`).toBeDefined();
      return (found as [string, unknown])[0];
    };
    const names = [
      ...tools.map(({ pkg, tool }) => `mcp__plugin_${PLUGIN().name}_${keyOf(pkg)}__${tool.name}`),
      ...Object.keys(SERVERS()).map((key) => `mcp__plugin_${PLUGIN().name}_${key}__iris_server_profiles`),
    ];
    const longest = names.reduce((best, name) => (name.length > best.length ? name : best), "");
    expect(longest.length, `${longest} is ${longest.length} characters`).toBeLessThanOrEqual(64);
    // With the full bin name as the key, the interop server's longest tool would be over the limit: the short keys are what keep it under.
    const interop = tools.filter(({ pkg }) => pkg === "iris-interop-mcp").map(({ tool }) => `mcp__plugin_${PLUGIN().name}_iris-interop-mcp__${tool.name}`);
    expect(Math.max(...interop.map((name) => name.length)), "the full bin name as the key goes over 64").toBeGreaterThan(64);
  });
});

describe("what the plugin does not carry (AC 42.8.3; decision #106)", () => {
  it("has no hooks directory, no hooks key in plugin.json and no CLAUDE.md at its root", () => {
    const root = join(REPO_ROOT, PACK_DIR);
    expect(existsSync(join(root, "hooks")), "no hooks/ directory").toBe(false);
    expect(existsSync(join(root, ".claude-plugin", "hooks")), "no .claude-plugin/hooks").toBe(false);
    expect(Object.keys(PLUGIN()), "no hooks key").not.toContain("hooks");
    expect(existsSync(join(root, "CLAUDE.md")), "no CLAUDE.md").toBe(false);
  });

  it("the plugin root holds only what the pack holds: skills, the rule's three forms, the notice, the README and the two plugin files", () => {
    const top = readdirSync(join(REPO_ROOT, PACK_DIR)).sort();
    expect(top).toEqual([".claude-plugin", ".mcp.json", "IRIS-MCP-THIRD-PARTY-NOTICES.md", "README.md", "rules", "skills"].sort());
    expect(readdirSync(join(REPO_ROOT, PACK_DIR, ".claude-plugin"))).toEqual(["plugin.json"]);
  });

  it("the plugin ships the notice at its root, equal to the canonical notice (AD-28: the notice ships wherever the skills ship)", () => {
    const canonical = readFileSync(join(REPO_ROOT, "skills-pack-src", "IRIS-MCP-THIRD-PARTY-NOTICES.md"));
    expect(readFileSync(join(REPO_ROOT, PACK_DIR, "IRIS-MCP-THIRD-PARTY-NOTICES.md")).equals(canonical)).toBe(true);
  });
});
